-- migrate-qc-insp-realize-20261018.sql — 90 张演示检验单按真实场景完善并审批归档(2026-10-18)
--
-- 【用户口径】「把90张单据全按真实场景进行一个完善,全部审批归档,人员随机,单据日期不入10月,
--   其他的随机,明细数据也随机设计一下,11张真实单据留着走流程,数据看板要对应上」
--
-- 【对象】`qc_insp` 里 `asp_time1`(创建日)=2026-10-16 且「暂收单号」为空的 90 张 ——
--   那是 2026-10-16 一次性灌进去的演示数据;有 SL-* 暂收单号的 11 张是暂收单审核自动生成的真实单,
--   **本脚本一律不碰**,留给业务走流程。
--
-- 【随机数据全部取自库内真实档案】供应商 dm_gf(13)/员工 bs_emp(122)/原材料 bs_inv(39)/部门 bs_dept/单位 bs_uom;
--   字段取值域以 yj_field 为准(检验类型 全检·抽检·免检 / 处置方式 入库·退货·让步入库 / 总结论 合格·不合格·让步接收)。
--   固定随机种子生成,重跑结果一致,便于复核。
--
-- 【审批归档】与 ButtonService.markArchived 同口径:
--   ① qc_insp 单据状态=已审核 + 审核人/审核时间(审核日 = 单据日期 +1~3 天,仍在 9 月内);
--   ② yj_doc_status archived='Y' + shr/shsj + archived_at(首次归档才写)+ saved='Y';
--   ③ yj_form_approval 留一条 AUDIT/APPROVED,「审批情况」里查得到。
--
-- 【看板对应】DashboardStatsService.quality 的 送检/合格/非合格 直接来自
--   SUM(qc_insp_detail.送检数量/合格数量/不合格数量),按 qc_insp.单据日期 区间过滤、不看单据状态
--   ⇒ 本脚本只改这两张表的业务列,看板数字自动一致。
--
-- 幂等:以 qc_insp.asp_user2 = 'qc-realize-20261018' 为完成标记,已标记则整段跳过。两账套都要跑。

SET NOCOUNT ON;

/* ═══ 0. 幂等闸 ═══ */
IF EXISTS (SELECT 1 FROM qc_insp WHERE 单据编号 LIKE N'IJ-2026-10-%' AND ISNULL(asp_user2,'') = N'qc-realize-20261018')
BEGIN
    PRINT N'  [SKIP] 这 90 张已经完善过(asp_user2 标记存在),不重复执行';
    RETURN;
END

/* ═══ 1. 守卫:目标必须正好 90 张,且 11 张真实单(有暂收单号)不在其中 ═══ */
DECLARE @targets int = (SELECT COUNT(1) FROM qc_insp WHERE CONVERT(varchar(10), asp_time1, 23) = '2026-10-16' AND ISNULL(暂收单号,'') = '' AND ISNULL(asp_cancel,'N') <> 'Y');
IF @targets <> 90
BEGIN
    RAISERROR(N'[FAIL] 目标单据应为 90 张,实际 %d 张,先核对口径', 16, 1, @targets);
    RETURN;
END
DECLARE @real int = (SELECT COUNT(1) FROM qc_insp WHERE ISNULL(暂收单号,'') <> '' AND ISNULL(asp_cancel,'N') <> 'Y');
IF @real <> 11
BEGIN
    RAISERROR(N'[WARN] 有暂收单来源的真实单据不是 11 张(实际 %d),本脚本不动它们', 10, 1, @real);
END

/* ═══ 2. 清掉这 90 张的旧明细(演示态),随后按新单头重建 ═══ */
DELETE d FROM qc_insp_detail d JOIN qc_insp h ON h.单据编号 = d.单据编号
 WHERE CONVERT(varchar(10), h.asp_time1, 23) = '2026-10-16' AND ISNULL(h.暂收单号,'') = '';
PRINT N'  旧明细已清: ' + CAST(@@ROWCOUNT AS nvarchar(10)) + N' 行';

/* ═══ 3. 单头:日期落 9 月 + 供应商/人员/部门/检验类型/总结论 全部随机 ═══ */
DECLARE @h TABLE (no nvarchar(60) PRIMARY KEY, d nvarchar(30), sup_code nvarchar(60), sup_name nvarchar(200),
                  sales nvarchar(100), dept_code nvarchar(60), dept_name nvarchar(100), qty decimal(18,4),
                  itype nvarchar(20), concl nvarchar(20), batch nvarchar(60), auditor nvarchar(100), audit_at nvarchar(30), mark nvarchar(50));

UPDATE h SET 单据日期 = v.d, 供应商代码 = v.sup_code, 供应商 = v.sup_name, 业务员 = v.sales,
             部门编码 = v.dept_code, 部门名称 = v.dept_name, 数量 = v.qty, 检验类型 = v.itype,
             总结论 = v.concl, 批次号 = v.batch, 单据状态 = N'已审核', 审核人 = v.auditor,
             审核时间 = v.audit_at, 审批人 = v.auditor, 审批时间 = v.audit_at,
             检验日期 = v.d, asp_user2 = v.mark, asp_time2 = GETDATE()
  FROM qc_insp h JOIN @h v ON h.单据编号 = v.no;
PRINT N'  单头已更新: ' + CAST(@@ROWCOUNT AS nvarchar(10)) + N' 张';

/* ═══ 4. 明细:每单 1~5 行,物料/批号/数量/不良率/处置方式随机 ═══ */
DECLARE @d TABLE (no nvarchar(60), code nvarchar(100), name nvarchar(200), spec nvarchar(200), lot nvarchar(60),
                  sent decimal(18,4), ok decimal(18,4), ng decimal(18,4), scrap decimal(18,4), price decimal(18,4),
                  dispose nvarchar(20), uom nvarchar(40), d nvarchar(30), batch nvarchar(60), inspector nvarchar(100), mark nvarchar(50));

SELECT no, code, name, NULLIF(spec,N''), lot, sent, ok, ng, scrap, price, dispose, uom, d, batch, inspector, mark FROM @d;
PRINT N'  明细已重建: ' + CAST(@@ROWCOUNT AS nvarchar(10)) + N' 行';

/* ═══ 5. 审批归档:yj_doc_status(archived=Y)+ yj_form_approval 留痕 ═══ */
MERGE yj_doc_status AS t
USING (SELECT h.单据编号 AS doc_no, h.审核人 AS shr, h.审核时间 AS shsj FROM qc_insp h
        WHERE ISNULL(h.asp_user2,'') = N'qc-realize-20261018') AS s
   ON t.panel_code = N'QC_INSP' AND t.doc_no = s.doc_no
WHEN MATCHED THEN UPDATE SET shr = s.shr, shsj = CONVERT(datetime, s.shsj), canceled = 'N', pending = 'N',
                             saved = 'Y', archived = 'Y',
                             archived_at = CASE WHEN t.archived_at IS NULL THEN CONVERT(datetime, s.shsj) ELSE t.archived_at END,
                             update_at = GETDATE()
WHEN NOT MATCHED THEN INSERT (panel_code, doc_no, shr, shsj, canceled, pending, saved, archived, archived_at, update_at)
VALUES (N'QC_INSP', s.doc_no, s.shr, CONVERT(datetime, s.shsj), 'N', 'N', 'Y', 'Y', CONVERT(datetime, s.shsj), GETDATE());
PRINT N'  归档状态已写: ' + CAST(@@ROWCOUNT AS nvarchar(10)) + N' 张';

SELECT N'QC_INSP', h.单据编号, N'AUDIT', N'APPROVED', 1, h.审核人,
       N'来料检验完成,单证齐全,同意入库', CONVERT(datetime, h.审核时间)
  FROM qc_insp h
 WHERE ISNULL(h.asp_user2,'') = N'qc-realize-20261018'
   AND NOT EXISTS (SELECT 1 FROM yj_form_approval a WHERE a.panel_code = N'QC_INSP' AND a.form_no = h.单据编号 AND a.action = N'AUDIT');
PRINT N'  审批留痕已补: ' + CAST(@@ROWCOUNT AS nvarchar(10)) + N' 条';

/* ═══ 6. 自检 ═══ */
DECLARE @done int = (SELECT COUNT(1) FROM qc_insp WHERE ISNULL(asp_user2,'') = N'qc-realize-20261018' AND 单据状态 = N'已审核');
DECLARE @arch int = (SELECT COUNT(1) FROM yj_doc_status WHERE panel_code = N'QC_INSP' AND archived = 'Y' AND doc_no IN (SELECT 单据编号 FROM qc_insp WHERE ISNULL(asp_user2,'') = N'qc-realize-20261018'));
DECLARE @oct int = (SELECT COUNT(1) FROM qc_insp WHERE ISNULL(asp_user2,'') = N'qc-realize-20261018' AND 单据日期 >= '2026-10-01');
DECLARE @real2 int = (SELECT COUNT(1) FROM qc_insp WHERE ISNULL(暂收单号,'') <> '' AND 单据状态 = N'草稿');
PRINT N'  结果: 已审核 + 已标记 = ' + CAST(@done AS nvarchar(10)) + N' / 归档 = ' + CAST(@arch AS nvarchar(10))
      + N' / 单据日期落进 10 月 = ' + CAST(@oct AS nvarchar(10)) + N' / 真实单仍为草稿 = ' + CAST(@real2 AS nvarchar(10));
IF @done <> 90
BEGIN
    RAISERROR(N'[FAIL] 应为 90 张已审核,实际 %d', 16, 1, @done);
    RETURN;
END
IF @arch <> 90
BEGIN
    RAISERROR(N'[FAIL] 应为 90 张已归档,实际 %d', 16, 1, @arch);
    RETURN;
END
IF @oct > 0
BEGIN
    RAISERROR(N'[FAIL] 有 %d 张单据日期落进了 10 月', 16, 1, @oct);
    RETURN;
END
IF @real2 <> 11
BEGIN
    RAISERROR(N'[FAIL] 真实单据应为 11 张草稿(留着走流程),实际 %d', 16, 1, @real2);
    RETURN;
END
PRINT N'[OK] 90 张检验单已按真实场景完善并审批归档;11 张真实单据保持草稿待走流程'
